Async JavaScript::Iterables and generato.syntax:
function* name(parameters) { yield value; }
async function* name(parameters) { yield value; }
for (const value of iterable) { }
for await (const value of asyncIterable) { }

example.code:
async function* doubled(values) {
  for await (const value of values) yield value * 2;
}

const source = (async function* () {
  yield 1;
  yield 2;
})();

for await (const value of doubled(source)) {
  console.log(value);
}

const tasks = [
  fetch("/profile"),
  fetch("/recommendations"),
];

const results = await Promise.allSettled(tasks);
for (const result of results) {
  if (result.status === "fulfilled") {
    console.log(result.value);
  } else {
    console.error(result.reason);
  }
}

